/**
 * 3D Canvas renderer for the 5-body simulation
 */

import type { SimulationState, Vec3 } from '../types';

interface Camera {
  target: Vec3;
  distance: number;
  azimuth: number;   // Rotation around Z axis (horizontal rotation)
  elevation: number;  // Angle from XY plane (vertical rotation)
}

export class Renderer {
  private canvas: HTMLCanvasElement;
  private ctx: CanvasRenderingContext2D;
  private camera: Camera;
  private trails: Vec3[][] = []; // Trail for each body (dynamic size)
  private maxTrailLength = 300;
  private useOrthographic = false;

  constructor(canvas: HTMLCanvasElement) {
    this.canvas = canvas;
    const ctx = canvas.getContext('2d');
    if (!ctx) {
      throw new Error('Could not get 2D context');
    }
    this.ctx = ctx;

    // Initialize camera with better default view
    this.camera = {
      target: { x: 0, y: 0, z: 0 },
      distance: 30,
      azimuth: Math.PI / 4,     // 45 degrees around Z
      elevation: Math.PI / 6     // 30 degrees up from XY plane
    };

    this.setupInteraction();
  }

  private setupInteraction(): void {
    let isDragging = false;
    let isPanning = false;
    let lastX = 0;
    let lastY = 0;

    this.canvas.addEventListener('mousedown', (e) => {
      isDragging = true;
      isPanning = e.shiftKey || e.button === 1;
      lastX = e.clientX;
      lastY = e.clientY;
      e.preventDefault();
    });

    this.canvas.addEventListener('mousemove', (e) => {
      if (!isDragging) return;

      const dx = e.clientX - lastX;
      const dy = e.clientY - lastY;

      // Switch back to perspective on user interaction
      this.useOrthographic = false;

      if (isPanning) {
        // Pan in screen space
        this.panCamera(dx, dy);
      } else {
        // Rotate around target
        this.rotateCamera(dx, dy);
      }

      lastX = e.clientX;
      lastY = e.clientY;
    });

    this.canvas.addEventListener('mouseup', () => {
      isDragging = false;
      isPanning = false;
    });

    this.canvas.addEventListener('mouseleave', () => {
      isDragging = false;
      isPanning = false;
    });

    this.canvas.addEventListener('auxclick', (e) => {
      if (e.button === 1) {
        e.preventDefault();
      }
    });

    this.canvas.addEventListener('wheel', (e) => {
      e.preventDefault();
      // Switch back to perspective on user interaction
      this.useOrthographic = false;
      this.zoomCamera(e.deltaY);
    });
  }

  /**
   * Get camera position in world space
   */
  private getCameraPosition(): Vec3 {
    const x = this.camera.target.x + this.camera.distance * Math.cos(this.camera.elevation) * Math.cos(this.camera.azimuth);
    const y = this.camera.target.y + this.camera.distance * Math.cos(this.camera.elevation) * Math.sin(this.camera.azimuth);
    const z = this.camera.target.z + this.camera.distance * Math.sin(this.camera.elevation);
    return { x, y, z };
  }

  /**
   * Get camera basis vectors (right, up, forward)
   */
  private getCameraBasis(): { right: Vec3; up: Vec3; forward: Vec3 } {
    // Forward: from camera to target (normalized)
    const camPos = this.getCameraPosition();
    const fx = this.camera.target.x - camPos.x;
    const fy = this.camera.target.y - camPos.y;
    const fz = this.camera.target.z - camPos.z;
    const flen = Math.sqrt(fx * fx + fy * fy + fz * fz);
    const forward = { x: fx / flen, y: fy / flen, z: fz / flen };

    // World up vector
    const worldUp = { x: 0, y: 0, z: 1 };

    // Right: cross(forward, worldUp)
    const rx = forward.y * worldUp.z - forward.z * worldUp.y;
    const ry = forward.z * worldUp.x - forward.x * worldUp.z;
    const rz = forward.x * worldUp.y - forward.y * worldUp.x;
    const rlen = Math.sqrt(rx * rx + ry * ry + rz * rz);
    const right = { x: rx / rlen, y: ry / rlen, z: rz / rlen };

    // Up: cross(right, forward)
    const ux = right.y * forward.z - right.z * forward.y;
    const uy = right.z * forward.x - right.x * forward.z;
    const uz = right.x * forward.y - right.y * forward.x;
    const up = { x: ux, y: uy, z: uz };

    return { right, up, forward };
  }

  private rotateCamera(dx: number, dy: number): void {
    // Rotate azimuth (left/right)
    this.camera.azimuth -= dx * 0.005;

    // Rotate elevation (up/down) with limits
    this.camera.elevation += dy * 0.005;
    this.camera.elevation = Math.max(-Math.PI / 2 + 0.01, Math.min(Math.PI / 2 - 0.01, this.camera.elevation));
  }

  private panCamera(dx: number, dy: number): void {
    const basis = this.getCameraBasis();

    // Pan speed proportional to distance
    const panSpeed = this.camera.distance * 0.001;

    // Move target in screen space (right and up directions)
    this.camera.target.x -= basis.right.x * dx * panSpeed;
    this.camera.target.y -= basis.right.y * dx * panSpeed;
    this.camera.target.z -= basis.right.z * dx * panSpeed;

    this.camera.target.x += basis.up.x * dy * panSpeed;
    this.camera.target.y += basis.up.y * dy * panSpeed;
    this.camera.target.z += basis.up.z * dy * panSpeed;
  }

  private zoomCamera(delta: number): void {
    // Zoom toward/away from target
    const zoomFactor = delta > 0 ? 1.1 : 0.9;
    this.camera.distance *= zoomFactor;
    this.camera.distance = Math.max(5, Math.min(150, this.camera.distance));
  }

  /**
   * Project 3D point to 2D screen coordinates
   */
  private project(p: Vec3): { x: number; y: number; z: number } | null {
    const camPos = this.getCameraPosition();
    const basis = this.getCameraBasis();

    // Transform to camera space
    const dx = p.x - camPos.x;
    const dy = p.y - camPos.y;
    const dz = p.z - camPos.z;

    // Project onto camera axes
    const camX = dx * basis.right.x + dy * basis.right.y + dz * basis.right.z;
    const camY = dx * basis.up.x + dy * basis.up.y + dz * basis.up.z;
    const camZ = dx * basis.forward.x + dy * basis.forward.y + dz * basis.forward.z;

    // Behind camera check (only for perspective)
    if (!this.useOrthographic && camZ <= 0.1) return null;

    let screenX: number;
    let screenY: number;

    if (this.useOrthographic) {
      // Orthographic projection - scale factor based on distance
      const orthoScale = this.canvas.height / (this.camera.distance * 0.75);
      screenX = this.canvas.width / 2 + camX * orthoScale;
      screenY = this.canvas.height / 2 - camY * orthoScale;
    } else {
      // Perspective projection
      const fov = 60 * Math.PI / 180; // Field of view
      const scale = (this.canvas.height / 2) / Math.tan(fov / 2);
      screenX = this.canvas.width / 2 + (camX / camZ) * scale;
      screenY = this.canvas.height / 2 - (camY / camZ) * scale;
    }

    return { x: screenX, y: screenY, z: camZ };
  }

  /**
   * Clear trails
   */
  clearTrails(): void {
    this.trails = [];
  }

  /**
   * Render the current state
   */
  render(state: SimulationState): void {
    const { width, height } = this.canvas;

    // Clear canvas
    this.ctx.fillStyle = '#0f1422';
    this.ctx.fillRect(0, 0, width, height);

    // Ensure trails array matches number of bodies
    while (this.trails.length < state.bodies.length) {
      this.trails.push([]);
    }
    while (this.trails.length > state.bodies.length) {
      this.trails.pop();
    }

    // Update trails
    state.bodies.forEach((body, i) => {
      this.trails[i].push({ ...body.position });
      if (this.trails[i].length > this.maxTrailLength) {
        this.trails[i].shift();
      }
    });

    // Draw reference grid at z=0
    this.drawGrid();

    // Draw trails
    this.drawTrails();

    // Draw bodies
    this.drawBodies(state);

    // Draw labels
    this.drawLabels(state);
  }

  private drawGrid(): void {
    this.ctx.strokeStyle = 'rgba(255, 255, 255, 0.05)';
    this.ctx.lineWidth = 1;

    const gridSize = 20;
    const gridStep = 2;

    for (let x = -gridSize; x <= gridSize; x += gridStep) {
      const p1 = this.project({ x, y: -gridSize, z: 0 });
      const p2 = this.project({ x, y: gridSize, z: 0 });
      if (p1 && p2) {
        this.ctx.beginPath();
        this.ctx.moveTo(p1.x, p1.y);
        this.ctx.lineTo(p2.x, p2.y);
        this.ctx.stroke();
      }
    }

    for (let y = -gridSize; y <= gridSize; y += gridStep) {
      const p1 = this.project({ x: -gridSize, y, z: 0 });
      const p2 = this.project({ x: gridSize, y, z: 0 });
      if (p1 && p2) {
        this.ctx.beginPath();
        this.ctx.moveTo(p1.x, p1.y);
        this.ctx.lineTo(p2.x, p2.y);
        this.ctx.stroke();
      }
    }
  }

  private drawTrails(): void {
    // Dynamic colors based on body count
    // 2 bodies: [first binary 1, first binary 2]
    // 3 bodies: [first binary 1, first binary 2, shuttle]
    // 4 bodies: [first binary 1, first binary 2, second binary 1, second binary 2]
    // 5 bodies: [first binary 1, first binary 2, shuttle, second binary 1, second binary 2]
    const getColor = (index: number, totalBodies: number) => {
      // First binary is always indices 0, 1
      if (index < 2) return 'rgba(0, 198, 255, 0.4)';     // First binary - cyan

      // With shuttle: index 2 is shuttle
      // Without shuttle: indices 2, 3 are second binary
      if (totalBodies === 3 || (totalBodies === 5 && index === 2)) {
        return 'rgba(255, 255, 100, 0.6)'; // Shuttle - yellow
      }

      return 'rgba(255, 100, 0, 0.4)';                    // Second binary - orange
    };

    this.trails.forEach((trail, bodyIndex) => {
      if (trail.length < 2) return;

      this.ctx.strokeStyle = getColor(bodyIndex, this.trails.length);
      // Thicker line for shuttle if present
      const isShuttle = (this.trails.length === 3 && bodyIndex === 2) ||
                       (this.trails.length === 5 && bodyIndex === 2);
      this.ctx.lineWidth = isShuttle ? 2 : 1;
      this.ctx.beginPath();

      let first = true;
      for (const pos of trail) {
        const p = this.project(pos);
        if (p) {
          if (first) {
            this.ctx.moveTo(p.x, p.y);
            first = false;
          } else {
            this.ctx.lineTo(p.x, p.y);
          }
        }
      }
      this.ctx.stroke();
    });
  }

  private drawBodies(state: SimulationState): void {
    const totalBodies = state.bodies.length;

    // Dynamic colors based on body index and total count
    const getColor = (index: number) => {
      if (index < 2) return '#00c6ff';    // First binary - cyan

      // Shuttle detection
      if (totalBodies === 3 || (totalBodies === 5 && index === 2)) {
        return '#ffff00';  // Shuttle - yellow
      }

      return '#ff6400';                   // Second binary - orange
    };

    // Sort bodies by depth for proper z-ordering
    const projected = state.bodies.map((body, i) => ({
      body,
      index: i,
      proj: this.project(body.position)
    })).filter(item => item.proj !== null);

    projected.sort((a, b) => a.proj!.z - b.proj!.z);

    // Draw bodies
    projected.forEach(({ index, proj }) => {
      if (!proj) return;

      const color = getColor(index);
      // Shuttle is bigger
      const isShuttle = (totalBodies === 3 && index === 2) ||
                       (totalBodies === 5 && index === 2);
      const radius = isShuttle ? 8 : 5;

      // Glow effect
      const gradient = this.ctx.createRadialGradient(
        proj.x, proj.y, 0,
        proj.x, proj.y, radius * 2
      );
      gradient.addColorStop(0, color + 'ff');
      gradient.addColorStop(0.4, color + '88');
      gradient.addColorStop(1, color + '00');

      this.ctx.fillStyle = gradient;
      this.ctx.beginPath();
      this.ctx.arc(proj.x, proj.y, radius * 2, 0, Math.PI * 2);
      this.ctx.fill();

      // Core
      this.ctx.fillStyle = color;
      this.ctx.beginPath();
      this.ctx.arc(proj.x, proj.y, radius, 0, Math.PI * 2);
      this.ctx.fill();

      // Bright center
      this.ctx.fillStyle = '#ffffff';
      this.ctx.beginPath();
      this.ctx.arc(proj.x, proj.y, radius * 0.4, 0, Math.PI * 2);
      this.ctx.fill();
    });
  }

  private drawLabels(state: SimulationState): void {
    this.ctx.fillStyle = '#ffffff';
    this.ctx.font = '11px Inter, sans-serif';
    this.ctx.textAlign = 'left';

    const totalBodies = state.bodies.length;

    // Dynamic labels based on body count
    const getLabel = (index: number) => {
      // First binary is always indices 0, 1
      if (index < 2) return `B1-${index + 1}`;

      // Shuttle detection
      if (totalBodies === 3 || (totalBodies === 5 && index === 2)) {
        return 'Shuttle';
      }

      // Second binary
      // In 4-body mode: indices 2, 3 are B2
      // In 5-body mode: indices 3, 4 are B2
      if (totalBodies === 4) {
        return `B2-${index - 1}`;
      } else {
        return `B2-${index - 2}`;
      }
    };

    state.bodies.forEach((body, i) => {
      const p = this.project(body.position);
      if (p) {
        this.ctx.fillText(getLabel(i), p.x + 12, p.y - 8);
      }
    });
  }

  resize(width: number, height: number): void {
    this.canvas.width = width;
    this.canvas.height = height;
  }

  /**
   * Set camera to a preset view (orthographic)
   */
  setCameraPreset(preset: 'top' | 'side'): void {
    this.useOrthographic = true;

    if (preset === 'top') {
      // Looking straight down the Z axis
      this.camera.azimuth = 0;
      this.camera.elevation = Math.PI / 2 - 0.01;
      this.camera.distance = 80;
      this.camera.target = { x: 0, y: 0, z: 15 };
    } else if (preset === 'side') {
      // Looking along Y axis (camera in XZ plane, y=0)
      this.camera.azimuth = -Math.PI / 2;
      this.camera.elevation = 0;
      this.camera.distance = 80;
      this.camera.target = { x: 0, y: 0, z: 15 };
    }
  }
}
