/**
 * Main orchestration for the gravity simulation
 * Connects simulation, rendering, and UI layers
 */

import { Simulation } from './simulation/simulation';
import { Renderer } from './rendering/renderer';
import { Controls } from './ui/controls';
import type { SimulationParams } from './types';

class GravitySimulationApp {
  private simulation: Simulation;
  private renderer: Renderer;
  private controls: Controls;
  private isPlaying = false;
  private lastTime = 0;

  constructor() {
    // Get canvas element
    const canvas = document.getElementById('viewport') as HTMLCanvasElement;
    if (!canvas) {
      throw new Error('Canvas element not found');
    }

    // Initialize default parameters (matching HTML defaults from optimization)
    const defaultParams: SimulationParams = {
      binaryDistance: 33.2168,      // Z_1 (optimized from eval #361)
      binaryEccentricity: 0.95,     // e
      shuttleMass: 1.4201,          // Optimized (eval #361)
      shuttleInitialZ: 0.0,         // z_0
      shuttleInitialVz: 0.3427,     // v_z,0 (optimized from eval #361)
      binaryPhase: 3.3258,          // θ_1 (optimized upper binary phase, 190.6°)
      secondBinaryPhase: 4.4847,    // θ_2 (optimized lower binary phase, 257.0°)
      enableShuttle: true,          // Enabled by default
      enableSecondBinary: true,     // Enabled by default
      simulationSpeed: 1.0          // Normal speed
    };

    // Initialize layers
    this.simulation = new Simulation(defaultParams);
    this.renderer = new Renderer(canvas);
    this.controls = new Controls(
      (params) => this.handleParameterChange(params),
      (playing) => this.handlePlayPause(playing),
      () => this.handleReset()
    );

    // Start animation loop
    this.animate(0);

    // Handle window resize
    this.handleResize();
    window.addEventListener('resize', () => this.handleResize());

    // Setup view preset buttons
    const viewTopBtn = document.getElementById('viewTopBtn');
    const viewSideBtn = document.getElementById('viewSideBtn');
    viewTopBtn?.addEventListener('click', () => this.renderer.setCameraPreset('top'));
    viewSideBtn?.addEventListener('click', () => this.renderer.setCameraPreset('side'));
  }

  private handleParameterChange(params: SimulationParams): void {
    // Reset simulation with new parameters
    this.simulation.reset(params);
    this.renderer.clearTrails();

    // Render initial state
    if (!this.isPlaying) {
      this.renderer.render(this.simulation.getState());
    }
  }

  private handlePlayPause(playing: boolean): void {
    this.isPlaying = playing;
  }

  private handleReset(): void {
    const params = this.controls.getParameters();
    this.simulation.reset(params);
    this.renderer.clearTrails();
    this.renderer.render(this.simulation.getState());
  }

  private handleResize(): void {
    const canvas = document.getElementById('viewport') as HTMLCanvasElement;
    const container = canvas.parentElement;
    if (container) {
      const width = Math.min(container.clientWidth - 48, 800);
      const height = Math.min(width * 0.75, 600);
      this.renderer.resize(width, height);
      this.renderer.render(this.simulation.getState());
    }
  }

  private animate(timestamp: number): void {
    const deltaTime = this.lastTime ? (timestamp - this.lastTime) / 1000 : 0;
    this.lastTime = timestamp;

    if (this.isPlaying && deltaTime > 0) {
      // Get current simulation speed from controls
      const simSpeed = this.controls.getParameters().simulationSpeed;

      // Use adaptive time stepping for stability
      const dt = 0.01 * simSpeed; // Scaled timestep
      const substeps = 3; // Multiple substeps per frame

      for (let i = 0; i < substeps; i++) {
        this.simulation.step(dt);
      }
    }

    // Always render
    this.renderer.render(this.simulation.getState());

    requestAnimationFrame((t) => this.animate(t));
  }
}

// Initialize the app when DOM is ready
if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', () => {
    new GravitySimulationApp();
  });
} else {
  new GravitySimulationApp();
}

// Export factory function for embedding
export function create(containerId: string, params?: Partial<SimulationParams>): void {
  const container = document.getElementById(containerId);
  if (!container) {
    throw new Error(`Container element '${containerId}' not found`);
  }

  // For embedding support in future
  console.log('Gravity simulation initialized', params);
}
