/**
 * UI Controls for adjusting simulation parameters
 */

import type { SimulationParams } from '../types';

export type ParameterChangeCallback = (params: SimulationParams) => void;

export class Controls {
  private params: SimulationParams;
  private onParameterChange: ParameterChangeCallback;
  private onPlayPause: (isPlaying: boolean) => void;
  private onReset: () => void;

  // UI Elements
  private binaryDistanceSlider: HTMLInputElement;
  private binaryDistanceValue: HTMLElement;
  private binaryEccentricitySlider: HTMLInputElement;
  private binaryEccentricityValue: HTMLElement;
  private binaryPhaseSlider: HTMLInputElement;
  private binaryPhaseValue: HTMLElement;
  private secondBinaryPhaseSlider: HTMLInputElement;
  private secondBinaryPhaseValue: HTMLElement;
  private enableSecondBinaryCheckbox: HTMLInputElement;
  private enableShuttleCheckbox: HTMLInputElement;
  private shuttleMassSlider: HTMLInputElement;
  private shuttleMassValue: HTMLElement;
  private shuttlePositionSlider: HTMLInputElement;
  private shuttlePositionValue: HTMLElement;
  private shuttleVelocitySlider: HTMLInputElement;
  private shuttleVelocityValue: HTMLElement;
  private simulationSpeedSlider: HTMLInputElement;
  private simulationSpeedValue: HTMLElement;
  private playPauseBtn: HTMLButtonElement;
  private resetBtn: HTMLButtonElement;

  private isPlaying = false;

  constructor(
    onParameterChange: ParameterChangeCallback,
    onPlayPause: (isPlaying: boolean) => void,
    onReset: () => void
  ) {
    this.onParameterChange = onParameterChange;
    this.onPlayPause = onPlayPause;
    this.onReset = onReset;

    // Get DOM elements
    this.binaryDistanceSlider = this.getElement('binaryDistance') as HTMLInputElement;
    this.binaryDistanceValue = this.getElement('binaryDistanceValue');
    this.binaryEccentricitySlider = this.getElement('binaryEccentricity') as HTMLInputElement;
    this.binaryEccentricityValue = this.getElement('binaryEccentricityValue');
    this.binaryPhaseSlider = this.getElement('binaryPhase') as HTMLInputElement;
    this.binaryPhaseValue = this.getElement('binaryPhaseValue');
    this.secondBinaryPhaseSlider = this.getElement('secondBinaryPhase') as HTMLInputElement;
    this.secondBinaryPhaseValue = this.getElement('secondBinaryPhaseValue');
    this.enableSecondBinaryCheckbox = this.getElement('enableSecondBinary') as HTMLInputElement;
    this.enableShuttleCheckbox = this.getElement('enableShuttle') as HTMLInputElement;
    this.shuttleMassSlider = this.getElement('shuttleMass') as HTMLInputElement;
    this.shuttleMassValue = this.getElement('shuttleMassValue');
    this.shuttlePositionSlider = this.getElement('shuttlePosition') as HTMLInputElement;
    this.shuttlePositionValue = this.getElement('shuttlePositionValue');
    this.shuttleVelocitySlider = this.getElement('shuttleVelocity') as HTMLInputElement;
    this.shuttleVelocityValue = this.getElement('shuttleVelocityValue');
    this.simulationSpeedSlider = this.getElement('simulationSpeed') as HTMLInputElement;
    this.simulationSpeedValue = this.getElement('simulationSpeedValue');
    this.playPauseBtn = this.getElement('playPauseBtn') as HTMLButtonElement;
    this.resetBtn = this.getElement('resetBtn') as HTMLButtonElement;

    // Initialize parameters from slider values
    this.params = this.readParameters();

    // Setup event listeners
    this.setupEventListeners();

    // Update initial display values
    this.updateDisplayValues();
  }

  private getElement(id: string): HTMLElement {
    const element = document.getElementById(id);
    if (!element) {
      throw new Error(`Element with id '${id}' not found`);
    }
    return element;
  }

  private setupEventListeners(): void {
    // Binary distance
    this.binaryDistanceSlider.addEventListener('input', () => {
      this.params.binaryDistance = parseFloat(this.binaryDistanceSlider.value);
      this.updateDisplayValues();
      this.onParameterChange(this.params);
    });

    // Binary eccentricity
    this.binaryEccentricitySlider.addEventListener('input', () => {
      this.params.binaryEccentricity = parseFloat(this.binaryEccentricitySlider.value);
      this.updateDisplayValues();
      this.onParameterChange(this.params);
    });

    // Binary phase (upper binary)
    this.binaryPhaseSlider.addEventListener('input', () => {
      this.params.binaryPhase = parseFloat(this.binaryPhaseSlider.value);
      this.updateDisplayValues();
      this.onParameterChange(this.params);
    });

    // Second binary phase (lower binary)
    this.secondBinaryPhaseSlider.addEventListener('input', () => {
      this.params.secondBinaryPhase = parseFloat(this.secondBinaryPhaseSlider.value);
      this.updateDisplayValues();
      this.onParameterChange(this.params);
    });

    // Enable second binary checkbox
    this.enableSecondBinaryCheckbox.addEventListener('change', () => {
      this.params.enableSecondBinary = this.enableSecondBinaryCheckbox.checked;
      this.onParameterChange(this.params);
    });

    // Enable shuttle checkbox
    this.enableShuttleCheckbox.addEventListener('change', () => {
      this.params.enableShuttle = this.enableShuttleCheckbox.checked;
      this.onParameterChange(this.params);
    });

    // Shuttle mass
    this.shuttleMassSlider.addEventListener('input', () => {
      this.params.shuttleMass = parseFloat(this.shuttleMassSlider.value);
      this.updateDisplayValues();
      this.onParameterChange(this.params);
    });

    // Shuttle position
    this.shuttlePositionSlider.addEventListener('input', () => {
      this.params.shuttleInitialZ = parseFloat(this.shuttlePositionSlider.value);
      this.updateDisplayValues();
      this.onParameterChange(this.params);
    });

    // Shuttle velocity
    this.shuttleVelocitySlider.addEventListener('input', () => {
      this.params.shuttleInitialVz = parseFloat(this.shuttleVelocitySlider.value);
      this.updateDisplayValues();
      this.onParameterChange(this.params);
    });

    // Simulation speed
    this.simulationSpeedSlider.addEventListener('input', () => {
      this.params.simulationSpeed = parseFloat(this.simulationSpeedSlider.value);
      this.updateDisplayValues();
      // No need to reset simulation for speed change
    });

    // Play/Pause button
    this.playPauseBtn.addEventListener('click', () => {
      this.isPlaying = !this.isPlaying;
      this.playPauseBtn.textContent = this.isPlaying ? 'Pause' : 'Play';
      this.onPlayPause(this.isPlaying);
    });

    // Reset button
    this.resetBtn.addEventListener('click', () => {
      this.onReset();
    });
  }

  private readParameters(): SimulationParams {
    return {
      binaryDistance: parseFloat(this.binaryDistanceSlider.value),
      binaryEccentricity: parseFloat(this.binaryEccentricitySlider.value),
      binaryPhase: parseFloat(this.binaryPhaseSlider.value),
      secondBinaryPhase: parseFloat(this.secondBinaryPhaseSlider.value),
      enableSecondBinary: this.enableSecondBinaryCheckbox.checked,
      enableShuttle: this.enableShuttleCheckbox.checked,
      shuttleMass: parseFloat(this.shuttleMassSlider.value),
      shuttleInitialZ: parseFloat(this.shuttlePositionSlider.value),
      shuttleInitialVz: parseFloat(this.shuttleVelocitySlider.value),
      simulationSpeed: parseFloat(this.simulationSpeedSlider.value)
    };
  }

  private getPhaseLabel(phase: number): string {
    const pi = Math.PI;
    if (Math.abs(phase) < 0.1) return `${phase.toFixed(2)} (pericenter)`;
    if (Math.abs(phase - pi/2) < 0.1) return `${phase.toFixed(2)} (quarter)`;
    if (Math.abs(phase - pi) < 0.1) return `${phase.toFixed(2)} (apocenter)`;
    if (Math.abs(phase - 3*pi/2) < 0.1) return `${phase.toFixed(2)} (3/4)`;
    if (Math.abs(phase - 2*pi) < 0.1) return `${phase.toFixed(2)} (pericenter)`;
    return phase.toFixed(2);
  }

  private updateDisplayValues(): void {
    this.binaryDistanceValue.textContent = this.params.binaryDistance.toFixed(1);
    this.binaryEccentricityValue.textContent = this.params.binaryEccentricity.toFixed(2);
    this.binaryPhaseValue.textContent = this.getPhaseLabel(this.params.binaryPhase);
    this.secondBinaryPhaseValue.textContent = this.getPhaseLabel(this.params.secondBinaryPhase);
    this.shuttleMassValue.textContent = this.params.shuttleMass.toFixed(2);
    this.shuttlePositionValue.textContent = this.params.shuttleInitialZ.toFixed(1);
    this.shuttleVelocityValue.textContent = this.params.shuttleInitialVz.toFixed(2);
    this.simulationSpeedValue.textContent = this.params.simulationSpeed.toFixed(1) + 'x';
  }

  getParameters(): SimulationParams {
    return { ...this.params };
  }

  setPlaying(playing: boolean): void {
    this.isPlaying = playing;
    this.playPauseBtn.textContent = playing ? 'Pause' : 'Play';
  }
}
