/**
 * 5-body Newtonian gravity simulation
 * Implements Xia's shuttle-between-binaries configuration
 */

import type { Body, Vec3, SimulationState, SimulationParams } from '../types';

// Gravitational constant (dimensionless units)
const G = 1.0;

// Fixed reference values
const BINARY_PERICENTER = 1.0; // r_p: Distance between binary stars at pericenter
const BINARY_MASS_TOTAL = 2.0; // M_bin: Total mass of each binary

/**
 * Calculate orbital parameters for given eccentricity
 */
function calculateOrbitalParams(eccentricity: number) {
  const a = BINARY_PERICENTER / (1 - eccentricity);
  const vPericenter = Math.sqrt(G * BINARY_MASS_TOTAL * (2 / BINARY_PERICENTER - 1 / a));
  const vStar = vPericenter / 2;
  return { semiMajorAxis: a, vPericenter, vStar };
}

/**
 * Vector operations
 */
function vec3(x: number, y: number, z: number): Vec3 {
  return { x, y, z };
}

function add(a: Vec3, b: Vec3): Vec3 {
  return { x: a.x + b.x, y: a.y + b.y, z: a.z + b.z };
}

function scale(v: Vec3, s: number): Vec3 {
  return { x: v.x * s, y: v.y * s, z: v.z * s };
}

/**
 * Calculate separation vector and relative velocity for a binary system
 * at a given true anomaly (angle from pericenter).
 *
 * For a binary with equal masses, the returned values represent the separation
 * vector from star 1 to star 2. Each star is positioned at ±(x,y)/2 from the COM.
 *
 * @param trueAnomaly - angle from pericenter (radians)
 * @param eccentricity - orbital eccentricity
 * @param semiMajorAxis - semi-major axis of the relative orbit
 * @param totalMass - total mass of the binary system
 * @returns separation vector and relative velocity in orbital plane
 */
function calculateKeplerOrbit(
  trueAnomaly: number,
  eccentricity: number,
  semiMajorAxis: number,
  totalMass: number
): { x: number; y: number; vx: number; vy: number } {
  // Distance from focus (center of mass) at this true anomaly
  const r = semiMajorAxis * (1 - eccentricity * eccentricity) / (1 + eccentricity * Math.cos(trueAnomaly));

  // Position in orbital plane (pericenter along +x axis)
  const x = r * Math.cos(trueAnomaly);
  const y = r * Math.sin(trueAnomaly);

  // Velocity components using orbital mechanics
  const h = Math.sqrt(G * totalMass * semiMajorAxis * (1 - eccentricity * eccentricity)); // specific angular momentum
  const vr = (G * totalMass / h) * eccentricity * Math.sin(trueAnomaly); // radial velocity
  const vt = h / r; // tangential velocity

  // Velocity components in orbital plane
  const vx = vr * Math.cos(trueAnomaly) - vt * Math.sin(trueAnomaly);
  const vy = vr * Math.sin(trueAnomaly) + vt * Math.cos(trueAnomaly);

  return { x, y, vx, vy };
}

/**
 * Create initial conditions with configurable eccentricity and phase
 */
export function createInitialState(params: SimulationParams): SimulationState {
  const {
    shuttleMass,
    binaryDistance,        // Z_1
    binaryEccentricity,    // e
    shuttleInitialZ,       // z_0
    shuttleInitialVz,      // v_z,0
    binaryPhase,           // θ_1: true anomaly for first binary (0 = pericenter, π = apocenter)
    secondBinaryPhase,     // θ_2: true anomaly for second binary
    enableShuttle,
    enableSecondBinary
  } = params;

  // Calculate orbital parameters for given eccentricity
  const { semiMajorAxis } = calculateOrbitalParams(binaryEccentricity);

  const bodies: Body[] = [];

  // First binary at z = +Z_1
  // Calculate separation vector at the specified true anomaly
  // The separation vector points from star 1 to star 2
  const separation = calculateKeplerOrbit(binaryPhase, binaryEccentricity, semiMajorAxis, BINARY_MASS_TOTAL);

  // For equal mass binary, each star is at ±separation/2 from COM
  bodies.push({
    mass: 1.0,
    position: vec3(-separation.x / 2, -separation.y / 2, binaryDistance),
    velocity: vec3(-separation.vx / 2, -separation.vy / 2, 0)
  });

  bodies.push({
    mass: 1.0,
    position: vec3(separation.x / 2, separation.y / 2, binaryDistance),
    velocity: vec3(separation.vx / 2, separation.vy / 2, 0)
  });

  // Shuttle at z = z_0 (on z-axis, moving toward first binary) - optional
  if (enableShuttle) {
    bodies.push({
      mass: shuttleMass,
      position: vec3(0, 0, shuttleInitialZ),
      velocity: vec3(0, 0, shuttleInitialVz)
    });
  }

  // Second binary at z = -Z_1 (optional, opposite rotation sense)
  if (enableSecondBinary) {
    // Second binary uses adjustable phase, rotates opposite direction
    // Rotate 90° around z-axis so binary axes are orthogonal
    const secondBinaryPhaseRotated = secondBinaryPhase + Math.PI / 2;
    const separation2 = calculateKeplerOrbit(secondBinaryPhaseRotated, binaryEccentricity, semiMajorAxis, BINARY_MASS_TOTAL);

    bodies.push({
      mass: 1.0,
      position: vec3(-separation2.x / 2, -separation2.y / 2, -binaryDistance),
      velocity: vec3(separation2.vx / 2, separation2.vy / 2, 0) // Opposite rotation
    });

    bodies.push({
      mass: 1.0,
      position: vec3(separation2.x / 2, separation2.y / 2, -binaryDistance),
      velocity: vec3(-separation2.vx / 2, -separation2.vy / 2, 0) // Opposite rotation
    });
  }

  return {
    bodies,
    time: 0
  };
}

/**
 * Calculate gravitational acceleration on body i due to all other bodies
 */
function calculateAcceleration(bodies: Body[], i: number): Vec3 {
  let ax = 0, ay = 0, az = 0;

  for (let j = 0; j < bodies.length; j++) {
    if (i === j) continue;

    const dx = bodies[j].position.x - bodies[i].position.x;
    const dy = bodies[j].position.y - bodies[i].position.y;
    const dz = bodies[j].position.z - bodies[i].position.z;
    const distSq = dx * dx + dy * dy + dz * dz;
    const dist = Math.sqrt(distSq);
    const distCubed = distSq * dist;

    const factor = G * bodies[j].mass / distCubed;
    ax += factor * dx;
    ay += factor * dy;
    az += factor * dz;
  }

  return vec3(ax, ay, az);
}

/**
 * Time integration using RK4 (4th order Runge-Kutta)
 */
export class Simulation {
  private state: SimulationState;

  constructor(params: SimulationParams) {
    this.state = createInitialState(params);
  }

  getState(): SimulationState {
    return this.state;
  }

  reset(params: SimulationParams): void {
    this.state = createInitialState(params);
  }

  /**
   * Advance simulation by timestep dt using RK4 integrator
   */
  step(dt: number): void {
    const n = this.state.bodies.length;

    // Storage for RK4 intermediate values
    const k1_v: Vec3[] = [];
    const k1_x: Vec3[] = [];
    const k2_v: Vec3[] = [];
    const k2_x: Vec3[] = [];
    const k3_v: Vec3[] = [];
    const k3_x: Vec3[] = [];
    const k4_v: Vec3[] = [];
    const k4_x: Vec3[] = [];

    // Store original state
    const originalBodies = this.state.bodies.map(b => ({
      mass: b.mass,
      position: { ...b.position },
      velocity: { ...b.velocity }
    }));

    // k1: evaluate at current state
    for (let i = 0; i < n; i++) {
      k1_v[i] = calculateAcceleration(this.state.bodies, i);
      k1_x[i] = { ...this.state.bodies[i].velocity };
    }

    // k2: evaluate at t + dt/2 using k1
    const tempBodies2 = originalBodies.map((b, i) => ({
      mass: b.mass,
      position: add(b.position, scale(k1_x[i], dt / 2)),
      velocity: add(b.velocity, scale(k1_v[i], dt / 2))
    }));
    for (let i = 0; i < n; i++) {
      k2_v[i] = calculateAcceleration(tempBodies2, i);
      k2_x[i] = tempBodies2[i].velocity;
    }

    // k3: evaluate at t + dt/2 using k2
    const tempBodies3 = originalBodies.map((b, i) => ({
      mass: b.mass,
      position: add(b.position, scale(k2_x[i], dt / 2)),
      velocity: add(b.velocity, scale(k2_v[i], dt / 2))
    }));
    for (let i = 0; i < n; i++) {
      k3_v[i] = calculateAcceleration(tempBodies3, i);
      k3_x[i] = tempBodies3[i].velocity;
    }

    // k4: evaluate at t + dt using k3
    const tempBodies4 = originalBodies.map((b, i) => ({
      mass: b.mass,
      position: add(b.position, scale(k3_x[i], dt)),
      velocity: add(b.velocity, scale(k3_v[i], dt))
    }));
    for (let i = 0; i < n; i++) {
      k4_v[i] = calculateAcceleration(tempBodies4, i);
      k4_x[i] = tempBodies4[i].velocity;
    }

    // Combine: x_new = x + (dt/6) * (k1 + 2*k2 + 2*k3 + k4)
    for (let i = 0; i < n; i++) {
      const dv = add(
        add(k1_v[i], scale(add(k2_v[i], k3_v[i]), 2)),
        k4_v[i]
      );
      const dx = add(
        add(k1_x[i], scale(add(k2_x[i], k3_x[i]), 2)),
        k4_x[i]
      );

      this.state.bodies[i].velocity = add(
        originalBodies[i].velocity,
        scale(dv, dt / 6)
      );
      this.state.bodies[i].position = add(
        originalBodies[i].position,
        scale(dx, dt / 6)
      );
    }

    this.state.time += dt;
  }

  /**
   * Calculate total energy of the system (kinetic + potential)
   */
  calculateEnergy(): number {
    const bodies = this.state.bodies;
    let kinetic = 0;
    let potential = 0;

    // Kinetic energy
    for (const body of bodies) {
      const vSq = body.velocity.x ** 2 + body.velocity.y ** 2 + body.velocity.z ** 2;
      kinetic += 0.5 * body.mass * vSq;
    }

    // Potential energy
    for (let i = 0; i < bodies.length; i++) {
      for (let j = i + 1; j < bodies.length; j++) {
        const dx = bodies[j].position.x - bodies[i].position.x;
        const dy = bodies[j].position.y - bodies[i].position.y;
        const dz = bodies[j].position.z - bodies[i].position.z;
        const dist = Math.sqrt(dx * dx + dy * dy + dz * dz);
        potential -= G * bodies[i].mass * bodies[j].mass / dist;
      }
    }

    return kinetic + potential;
  }
}
